import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { parseLibraryJSON } from "@excalidraw/excalidraw/data/blob";
import { serializeLibraryAsJSON } from "@excalidraw/excalidraw/data/json";

import type { FileId } from "@excalidraw/element/types";

import { ICON_LIBRARIES_DIR } from "../useIconLibraries";

// generated by scripts/build-icon-libraries.mjs, so absent on a fresh clone
const manifest = (() => {
  try {
    return JSON.parse(
      readFileSync(`${ICON_LIBRARIES_DIR}/libraries.json`, "utf8"),
    );
  } catch {
    return null;
  }
})();

describe.skipIf(!manifest)("bundled icon libraries", () => {
  it("restores every icon with the file its element points at", () => {
    expect(manifest.libraries.length).toBeGreaterThan(0);
    expect(manifest.version).toBeTruthy();

    let total = 0;
    for (const library of manifest.libraries) {
      const items = parseLibraryJSON(
        readFileSync(`${ICON_LIBRARIES_DIR}/${library.file}`, "utf8"),
      );

      expect(items.length).toBeGreaterThan(0);
      for (const item of items) {
        const image = item.elements[0];
        expect(image.type).toBe("image");
        const fileId = (image as { fileId: FileId }).fileId;
        expect(item.files?.[fileId]).toBeDefined();
        expect(item.files?.[fileId].dataURL).toMatch(
          /^data:image\/svg\+xml;base64,/,
        );
        expect(item.name).toBeTruthy();
      }
      total += items.length;
    }

    expect(total).toBeGreaterThan(1000);
  });

  it("round-trips files through an export", () => {
    const library = manifest.libraries[0];
    const items = parseLibraryJSON(
      readFileSync(`${ICON_LIBRARIES_DIR}/${library.file}`, "utf8"),
    );
    const exported = JSON.parse(serializeLibraryAsJSON(items));
    expect(Object.keys(exported.files).length).toBe(items.length);
  });
});
